#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=6

TENANT_ID="cdf89f94-8c88-48fc-b11c-dd24af4380b4"
FUNCTION_APP="func-twopoint-website-api"
SWA_NAME="stapp-twopoint-admin"
# The Free plan is in a few regions only. The region does not change where the files are served from.
SWA_LOCATION="eastus2"
ADMIN_HOST="admin.twopoint.dev"
STAGING_REPO="tw0po1nt/twopoint-website-staging"
TOKEN_SECRET="AZURE_STATIC_WEB_APPS_API_TOKEN"
# set_secret has no repo argument, and gh reads the repo from GH_REPO.
export GH_REPO="$STAGING_REPO"

banner "Admin host: Static Web Apps, deploy token, and DNS"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Sign in to Azure and GitHub"
say "The wizard uses the Azure CLI and the GitHub CLI. It asks before each change."
if az account show >/dev/null 2>&1; then
  note "Azure: you are signed in as $(az account show --query user.name -o tsv)."
else
  step "A browser window opens for the Azure sign-in."
  pause "Press Enter to start the sign-in."
  az login --tenant "$TENANT_ID" >/dev/null
fi
if gh auth status >/dev/null 2>&1; then
  note "GitHub: you are signed in. The secret goes to $STAGING_REPO."
else
  warn "The GitHub CLI is not signed in. Run 'gh auth login' in another terminal now."
  pause "Press Enter when gh is signed in."
fi
RESOURCE_GROUP=$(az functionapp list --query "[?name=='$FUNCTION_APP'].resourceGroup | [0]" -o tsv)
[[ -n "$RESOURCE_GROUP" ]] || { warn "Cannot find $FUNCTION_APP in this subscription."; exit 1; }
note "The admin goes in the resource group of $FUNCTION_APP: $RESOURCE_GROUP."
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Create the Static Web Apps resource"
say "One app on the Free plan, with no Git link. The workflow sends each build with a deploy token."
if az staticwebapp show -n "$SWA_NAME" -g "$RESOURCE_GROUP" >/dev/null 2>&1; then
  note "$SWA_NAME already exists. Nothing to do."
elif confirm "Create the Static Web App '$SWA_NAME' (Free, $SWA_LOCATION) in $RESOURCE_GROUP?"; then
  az staticwebapp create -n "$SWA_NAME" -g "$RESOURCE_GROUP" -l "$SWA_LOCATION" --sku Free >/dev/null
  printf '  %s✓ created%s %s\n' "$GREEN" "$RESET" "$SWA_NAME"
else
  SKIPPED+=("Create the Static Web App $SWA_NAME on the Free plan, then run this wizard again")
  finish
  exit 0
fi
SKU=$(az staticwebapp show -n "$SWA_NAME" -g "$RESOURCE_GROUP" --query sku.name -o tsv)
[[ "$SKU" == "Free" ]] || warn "$SWA_NAME is on the '$SKU' plan, not on the Free plan."
DEFAULT_HOST=$(az staticwebapp show -n "$SWA_NAME" -g "$RESOURCE_GROUP" --query defaultHostname -o tsv)
note "Default host name: $DEFAULT_HOST"
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Put the deploy token in the staging repo"
say "The admin job of backend-staging.yml reads the secret $TOKEN_SECRET."
note "The prod repo gets no token, because it deploys no admin."
DEPLOY_TOKEN=$(az staticwebapp secrets list -n "$SWA_NAME" -g "$RESOURCE_GROUP" --query properties.apiKey -o tsv)
[[ -n "$DEPLOY_TOKEN" ]] || { warn "Cannot read the deploy token of $SWA_NAME."; exit 1; }
set_secret "$TOKEN_SECRET" "$DEPLOY_TOKEN"
unset DEPLOY_TOKEN
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Add the CNAME record in Cloudflare"
say "Cloudflare has the DNS of twopoint.dev."
# A local resolver keeps a "no such name" answer for up to 30 minutes, so ask the zone's name server.
ZONE_NS=$(dig +short NS "${ADMIN_HOST#*.}" | head -n1)
cname_target() { dig +short CNAME "$ADMIN_HOST" @"$ZONE_NS" | sed 's/\.$//'; }
if [[ "$(cname_target)" == "$DEFAULT_HOST" ]]; then
  note "$ADMIN_HOST already points to $DEFAULT_HOST. Nothing to do."
else
  open_url "https://dash.cloudflare.com/"
  step "Open twopoint.dev, then DNS > Records > Add record."
  step "Type: CNAME. Name: admin. Target: $DEFAULT_HOST"
  step "Proxy status: DNS only (gray cloud). Azure must see the CNAME to issue the certificate."
  step "Save the record."
  pause "Press Enter after you save the record."
  until [[ "$(cname_target)" == "$DEFAULT_HOST" ]]; do
    warn "$ADMIN_HOST does not point to $DEFAULT_HOST yet."
    confirm "Check again?" || { SKIPPED+=("CNAME admin → $DEFAULT_HOST in Cloudflare, DNS only"); finish; exit 0; }
  done
  printf '  %s✓ found%s %s → %s\n' "$GREEN" "$RESET" "$ADMIN_HOST" "$DEFAULT_HOST"
fi
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Add $ADMIN_HOST to the Static Web App"
say "Azure checks the CNAME and then issues a free certificate. This can take some minutes."
HOST_STATUS=$(az staticwebapp hostname show -n "$SWA_NAME" -g "$RESOURCE_GROUP" --hostname "$ADMIN_HOST" --query status -o tsv 2>/dev/null || true)
if [[ "$HOST_STATUS" == "Ready" ]]; then
  note "$ADMIN_HOST is already ready on $SWA_NAME. Nothing to do."
elif confirm "Add the custom domain $ADMIN_HOST to $SWA_NAME?"; then
  az staticwebapp hostname set -n "$SWA_NAME" -g "$RESOURCE_GROUP" --hostname "$ADMIN_HOST" >/dev/null
  HOST_STATUS=$(az staticwebapp hostname show -n "$SWA_NAME" -g "$RESOURCE_GROUP" --hostname "$ADMIN_HOST" --query status -o tsv)
  printf '  %s✓ added%s %s (status: %s)\n' "$GREEN" "$RESET" "$ADMIN_HOST" "$HOST_STATUS"
else
  SKIPPED+=("az staticwebapp hostname set -n $SWA_NAME -g $RESOURCE_GROUP --hostname $ADMIN_HOST")
fi
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Check the deployed admin"
say "The admin job deploys at each merge to main in the staging repo, after the backend."
note "Before the first deploy, the host shows the Azure placeholder page. Run this wizard again after the deploy."
if confirm "Start 'Deploy backend (staging)' on main now? It deploys the backend and then the admin."; then
  gh workflow run backend-staging.yml --ref main
  printf '  %s✓ started%s the workflow. Wait for the admin job to finish.\n' "$GREEN" "$RESET"
  open_url "https://github.com/$STAGING_REPO/actions/workflows/backend-staging.yml"
  pause "Press Enter when the admin job is done."
fi
check_header() {
  local url="$1" name="$2" expected="$3" actual
  actual=$(curl -sSI "$url" | tr -d '\r' | awk -F': ' -v name="$name" 'tolower($1) == tolower(name) { print $2 }' | tail -n1)
  if [[ "$actual" == "$expected" ]]; then
    printf '  %s✓%s %s sends %s: %s\n' "$GREEN" "$RESET" "$url" "$name" "$actual"
  else
    warn "$url sends $name: '${actual:-none}', not '$expected'."
    SKIPPED+=("Check $name on $url after the admin deploy")
  fi
}
check_header "https://$ADMIN_HOST/" "X-Robots-Tag" "noindex, nofollow"
check_header "https://$ADMIN_HOST/redirect/" "Cache-Control" "no-store"
step "Sign in on the admin with the author account."
open_url "https://$ADMIN_HOST/"
pause "Press Enter after the dashboard shows."

finish
}

run_wizard "$@"; exit
